public class PersonController {

    /** A person as the screen shows it, with how many statements were taken of them and the last one's
     *  due-total (n/a when it was) and date; none of either before their first statement; and the ids
     *  of their patrons. Their grade is the one in force on the sheet's today, and terms their own terms
     *  in force then (baseTerms those from the beginning of time, datedTerms those from a date); grades lists every grade
     *  they were given, each with its from-date (YYYY-MM-DD, none for the first); watched says whether
     *  the signed-in user watches them; clashing says whether their name or an alias is used on another sheet
     *  of the sheet's tree; origin is the sheet they were transferred from, null for anyone else. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version, int statementCount,
            String statedTotal, String statementDate, boolean retired, String retiredFrom,
            List<RetirementView> retirements,
            boolean held, List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms, Integer baseTerms,
            List<TermsView> datedTerms, String contact,
            List<String> aliases, boolean clashing, String origin, List<String> tags, List<String> snapshots,
            List<String> statementLines, String flag) {

        public static PersonView of(Person person, LocalDate today, List<Statement> statements, List<Long> patronIds,
                boolean watched, boolean clashing, List<PersonSnapshot> snapshots) {
            Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
                    statements.size(),
                    last == null ? null : last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString(),
                    last == null ? null : last.getTakenOn().toString(),
                    person.isRetired(), person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
                    person.getRetirements().stream().map(RetirementView::of).toList(),
                    person.isHeld(), person.getHolds().stream().map(HoldView::of).toList(), patronIds,
                    watched, person.termsOn(today), person.getTerms(),
                    person.getDatedTerms().stream().map(TermsView::of).toList(), person.getContact(), person.getAliases(), clashing,
                    person.getOriginSheet(), person.getTags(), snapshots.stream().map(PersonSnapshot::line).toList(),
                    statementLines(statements), person.flagShownOn(today));
        }

        /** One line per statement standing, in the order they were taken (one taken as of an earlier date
         *  where it was taken, not by that date), as `<date> <due-total>` (n/a when it was). */
        private static List<String> statementLines(List<Statement> statements) {
            return statements.stream().sorted(Comparator.comparing(Statement::getId))
                    .map(s -> s.getTakenOn() + " " + (s.getDueTotal() == null ? "n/a" : s.getDueTotal().toPlainString()))
                    .toList();
        }
    }

    /** The date a person is retired from; none takes the sheet's today. */
    public record RetireRequest(LocalDate from) {
    }

    /** A flag's reason and the last date it is in force on. */
    public record FlagRequest(@Size(max = 1000) String reason, LocalDate until) {
    }

    private final PersonService service;
        return view(held, user.trim());
    }

    /** A hold that cannot be put on is refused with the reason, for the screen to show. */
    @ExceptionHandler(HoldRefusedException.class)
    @ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
    public Map<String, String> holdRefused(HoldRefusedException e) {
        return Map.of("message", e.getMessage());
    }

    /** Flag a person with a reason until a date. */
    @PostMapping("/{personId}/flag")
    public PersonView flag(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid FlagRequest request) {
        Person flagged = service.flag(sheetId.trim(), user.trim(), personId, request.reason(), request.until());
        return view(flagged, user.trim());
    }

    /** A flag that cannot be put on is refused with the reason, for the screen to show. */
    @ExceptionHandler(FlagRefusedException.class)
    @ResponseStatus(HttpStatus.FORBIDDEN)
    public Map<String, String> flagRefused(FlagRefusedException e) {
        return Map.of("message", e.getMessage());
    }

    /** Name another person on the sheet as the person's patron. */
    @PostMapping("/{personId}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
    private String originSheet;

    /** The sheet's today on which they arrived by transfer; null for anyone who did not. */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    /** The reason a steward flagged them for; null when never flagged. */
    @Column(name = "flag_reason")
    private String flagReason;

    /** The last date their flag is in force on; null when never flagged. */
    @Column(name = "flag_until")
    private LocalDate flagUntil;

    /** Their place in the sheet's list; set when they are first saved, next after everyone on the sheet. */
    @Column(name = "list_position", nullable = false)
    public void hold(LocalDate from, LocalDate to) {
        holds.add(new PersonHold(from, to));
    }

    /** Flag them with a reason until a date, replacing any flag they had. */
    public void flag(String reason, LocalDate until) {
        this.flagReason = reason;
        this.flagUntil = until;
    }

    /** Whether their flag is in force on a day (the sheet's today): it is on or before its until-date. */
    public boolean flaggedOn(LocalDate today) {
        return flagUntil != null && today != null && !today.isAfter(flagUntil);
    }

    /** The reason of their flag in force on a day (the sheet's today); null when none is. */
    public String flagShownOn(LocalDate today) {
        return flaggedOn(today) ? flagReason : null;
    }

